类主要{
    公共静态无效主（字符串[] args）{
        示例（）；
    }
    公共静态无效示例（）{
        Foo foo = new Foo(); //分配
        酒吧酒吧=新酒吧（）； //分配
        bar.setFoo(foo);
    }
}

类 Foo {}

类酒吧{
    私人 Foo foo;
    公共无效setFoo（Foo foo）{
        this.foo = foo;
    }
