2.    public volatile String lastUser; //发布的信息
3.
4.    public boolean authenticate(String user, String password) {
5.    boolean valid = passwordIsValid(user, password);
6.    if (valid) {
7.    User u = new User();
8.    activeUsers.add(u);
9.    lastUser = user;
10.    }
11.    return valid;
12.    }
13. }
```

